// Simple normalization: clean URLs, tag with source, remove obvious non-articles
// DeepSeek will handle Malaysia relevance + article classification

function cleanHtml(html) {
  if (!html) return '';
  return html.replace(/<[^>]*>/g, '').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&quot;/g, '"').replace(/&#39;/g, "'").trim();
}

function extractDomain(url) {
  if (!url) return 'unknown';
  try {
    const u = new URL(url.startsWith('http') ? url : 'http://' + url);
    return u.hostname.replace(/^www\./, '');
  } catch(e) {
    return 'unknown';
  }
}

function blockedPath(url) {
  const lower = String(url || '').toLowerCase();
  const blocked = ['/tag/', '/tags/', '/category/', '/categories/', '/archive', '/search', '/video/', '/videos/', '/gallery/', '/galleries/', '/photo/', '/photos/', '/topic/', '/topics/', '/live/'];
  return blocked.some(p => lower.includes(p));
}

const out = [];
for (let i = 0; i < items.length; i++) {
  const item = items[i].json || items[i];
  const src = item._source || 'unknown';
  const srcType = item._source_type || 'news';
  const title = cleanHtml(item.title || 'Untitled');
  const summary = cleanHtml(item.summary || item.contentSnippet || item.content || item.description || '');
  let url = item.url || item.link || item.guid || '';

  // Skip blocked URL paths
  if (blockedPath(url)) continue;

  const pubDate = item.pubDate || item.isoDate || item.datePublished || new Date().toISOString();

  out.push({
    json: {
      title,
      url,
      source: src,
      source_type: srcType,
      published_at: pubDate,
      summary: summary.substring(0, 800),
      domain: extractDomain(url),
    }
  });
}

// Deduplicate by URL
const seen = new Set();
const deduped = out.filter(item => {
  const key = item.json.url.split('?')[0].split('#')[0];
  if (!key || seen.has(key)) return false;
  seen.add(key);
  return true;
});

return deduped;

const inputItems = items;
const results = inputItems.map(item => item.json);

if (!results || results.length === 0) {
  return [];
}

const classificationData = results[0];
const classifications = classificationData?.classifications;

if (!classifications || !Array.isArray(classifications)) {
  console.log('DeepSeek classification failed or invalid:', JSON.stringify(classificationData));
  return [];
}

const classMap = {};
classifications.forEach(c => {
  classMap[String(c.index)] = c;
});

const out = [];
let kept = 0;
let filtered = 0;

inputItems.forEach((item, idx) => {
  const cls = classMap[String(idx)];
  if (!cls) {
    filtered++;
    return;
  }

  if (cls.is_article !== true || cls.is_malaysia_relevant !== true || cls.confidence < 0.3) {
    filtered++;
    return;
  }

  kept++;
  out.push({
    json: {
      title: item.json.title || 'Untitled',
      url: item.json.url || '',
      source: item.json.source || 'unknown',
      source_label: item.json.source || 'unknown',
      source_name: item.json.source || 'unknown',
      source_domain: item.json.domain || '',
      published_at: item.json.published_at || new Date().toISOString(),
      summary: item.json.summary || '',
      primary_category: cls.primary_category || 'nation',
      secondary_category: cls.secondary_category || 'general',
      location_text: cls.location_text || 'Malaysia',
      main_place_text: cls.location_text || 'Malaysia',
      source_type: item.json.source_type || 'news',
    }
  });
});

console.log('DeepSeek: kept=' + kept + ', filtered=' + filtered);

return out;

function cleanHtml(html) {
  if (!html) return '';
  return html.replace(/<[^>]*>/g, '').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&quot;/g, '"').replace(/&#39;/g, "'").trim();
}

function extractDomain(url) {
  if (!url) return 'unknown';
  try {
    const u = new URL(url.startsWith('http') ? url : 'http://' + url);
    return u.hostname.replace(/^www\./, '');
  } catch(e) {
    return 'unknown';
  }
}

function detectLocation(title, summary) {
  const text = (title + ' ' + summary).toLowerCase();
  if (/kuala lumpur|kl\b/i.test(text)) return 'Kuala Lumpur';
  if (/selangor/i.test(text)) return 'Selangor';
  if (/penang/i.test(text)) return 'Penang';
  if (/johor/i.test(text)) return 'Johor';
  if (/sabah/i.test(text)) return 'Sabah';
  if (/sarawak/i.test(text)) return 'Sarawak';
  if (/putrajaya/i.test(text)) return 'Putrajaya';
  if (/malacca|melaka/i.test(text)) return 'Melaka';
  if (/perak/i.test(text)) return 'Perak';
  if (/kedah/i.test(text)) return 'Kedah';
  if (/kelantan/i.test(text)) return 'Kelantan';
  if (/terengganu/i.test(text)) return 'Terengganu';
  if (/pahang/i.test(text)) return 'Pahang';
  if (/nsw|negeri sembilan/i.test(text)) return 'Negeri Sembilan';
  return 'Malaysia';
}

const out = [];
for (let i = 0; i < items.length; i++) {
  const item = items[i].json;
  const title = item.title || 'Untitled';
  const summary = item.summary || '';
  const url = item.url || '';
  const pubDate = item.published_at || new Date().toISOString();
  const isBursa = item.source_type === 'announcement';
  const location_text = item.location_text || detectLocation(title, summary);

  out.push({
    json: {
      source_domain: item.source_domain || extractDomain(url),
      source_name: item.source || 'unknown',
      source_type: isBursa ? 'announcement' : 'news',
      source_label: item.source || 'unknown',
      title,
      url,
      published_at: pubDate,
      summary: summary.substring(0, 500),
      primary_category: item.primary_category || 'nation',
      secondary_category: item.secondary_category || 'general',
      location_text,
      main_place_text: location_text,
      country: 'Malaysia',
    }
  });
}

return out;
